from _lib import *
u1=U("relwords","Who, which, that, whose, where","B1",
 "A relative clause adds information about a noun. Use who for people, which for things, that for either (in defining clauses), whose for possession and where for places.",
 "relative clause দিয়ে noun সম্পর্কে তথ্য যোগ হয়। মানুষ = who, জিনিস = which, দুটোই = that, যার = whose, যেখানে = where।",
 [("People / things","the client who called · the laptop which / that I bought"),("Possession / place","the colleague whose father is ill · the café where we met")],
 [("Who for people.","মানুষের জন্য who।","The man who interviewed me was very kind."),
  ("Which or that for things.","জিনিসের জন্য which বা that।","The phone that I bought last week has stopped working."),
  ("Whose = his / her / their / its.","যার, যাদের।","Rafi has a flatmate whose brother works at a bank."),
  ("Where for places (= in which).","জায়গার জন্য where।","This is the restaurant where we had our office party."),
  ("Drop who/which/that when it is the object.","object হলে who/that বাদ দেওয়া যায়।","The report (that) you sent is excellent.")],
 ["who","which","that","whose","where"],
 [("The man which called you is here.","The man who called you is here.","People take who, not which.","মানুষ হলে who।"),
  ("The house where I live in is small.","The house where I live is small. / The house I live in is small.","Where already includes 'in'.","where থাকলে in লাগবে না।"),
  ("This is the book which I bought it.","This is the book which I bought.","Don't repeat the object pronoun.","it আবার বসাবেন না।")],
 [C("Describing a colleague.","She's the manager ___ hired me.",["who","which","whose","where"],"who","A person, subject: who."),
  C("A gadget.","The printer ___ we ordered hasn't arrived.",["that","who","whose","where"],"that","A thing: that or which."),
  T("A new flatmate.","I share a flat with a guy ___ sister is a doctor.","relative word",["whose"],"Possession: whose."),
  T("Back home.","Rajshahi is the city ___ I grew up.","relative word",["where","in which"],"A place: where."),
  F("Pick the correct sentence.",["The client which complained has called again.","The client who complained has called again.","The client whose complained has called again.","The client who he complained has called again."],"The client who complained has called again.","Person: who, no extra pronoun."),
  B("যে মেয়েটা আমার পাশে বসে, সে খুব ভালো ডিজাইনার।",["The girl who sits next to me is a very good designer.","The girl which sits next to me is a very good designer.","The girl who she sits next to me is a very good designer.","The girl sits next to me she is a very good designer."],"The girl who sits next to me is a very good designer.","Who + verb, no repeated 'she'."),
  C("Office talk.","That's the meeting room ___ we had the interview in.",["—","where","who","whose"],"—","Object relative can be dropped; 'where' would clash with 'in'.",True),
  F("Pick the correct sentence.",["This is the app which I told you about it.","This is the app I told you about.","This is the app where I told you about.","This is the app who I told you about."],"This is the app I told you about.","Object pronoun dropped, preposition at the end.",True)])
u2=U("commas","Defining vs non-defining clauses","B2",
 "A defining clause tells us which one and has no commas. A non-defining clause adds extra information between commas; it uses who or which, never that, and you cannot drop the relative word.",
 "defining clause বলে দেয় কোনটা (কমা নেই)। non-defining clause অতিরিক্ত তথ্য দেয়, দুই পাশে কমা থাকে, আর সেখানে that বসে না।",
 [("Defining","My brother who lives in London is a doctor. (I have more than one brother.)"),("Non-defining","My brother, who lives in London, is a doctor. (I have one brother.)"),("Which for a whole idea",", which: He passed the exam, which surprised everyone.")],
 [("Names and unique people always take non-defining clauses.","নাম বা একমাত্র ব্যক্তির পরে কমা।","Mr Hasan, who joined last year, leads the team."),
  ("No 'that' after a comma.","কমার পরে that নয়।","Dhaka, which is very crowded, is growing fast."),
  ("Defining clauses have no commas.","কোনটা বোঝাতে কমা লাগে না।","The staff who work weekends get extra pay."),
  (", which can refer to a whole sentence.","পুরো বাক্যের কথা বলতে , which।","The flight was cancelled, which meant another night in Dubai."),
  ("Commas change the meaning.","কমা দিলে অর্থ বদলে যায়।","The employees, who were late, were warned. (all were late)")],
 ["comma","no that","extra information","which one?"],
 [("My mother, that is a teacher, lives in Bogura.","My mother, who is a teacher, lives in Bogura.","No 'that' in non-defining clauses.","কমার পরে who/which।"),
  ("Dhaka which is the capital is very busy.","Dhaka, which is the capital, is very busy.","A name needs commas around extra information.","নামের পরে কমা।"),
  ("He was late again, that annoyed the boss.","He was late again, which annoyed the boss.","A whole idea takes , which.","পুরো ঘটনার জন্য , which।")],
 [C("A known person.","Our CEO, ___ studied at BUET, is an engineer.",["who","that","which","whose"],"who","Non-defining, person: who."),
  C("A city.","Sylhet, ___ is famous for tea, is beautiful in winter.",["which","that","where","who"],"which","Non-defining, thing: which."),
  T("A surprise.","The client paid early, ___ was a nice surprise.","relative word",["which"],"A whole idea: , which."),
  T("Family.","My father, ___ is retired, now grows vegetables.","relative word",["who"],"Non-defining, person: who."),
  F("Pick the correct sentence.",["Rafi's office, that is in Gulshan, is very modern.","Rafi's office, which is in Gulshan, is very modern.","Rafi's office which is in Gulshan, is very modern.","Rafi's office, where is in Gulshan, is very modern."],"Rafi's office, which is in Gulshan, is very modern.","Commas + which."),
  B("আমার একমাত্র বোন, যে কানাডায় থাকে, আগামী মাসে আসছে।",["My only sister, who lives in Canada, is coming next month.","My only sister who lives in Canada is coming next month.","My only sister, that lives in Canada, is coming next month.","My only sister, which lives in Canada, is coming next month."],"My only sister, who lives in Canada, is coming next month.","Only one sister: commas + who."),
  F("Which sentence means only some staff got a bonus?",["The staff, who met the target, got a bonus.","The staff who met the target got a bonus.","The staff, that met the target, got a bonus.","The staff which met the target got a bonus."],"The staff who met the target got a bonus.","Defining: only those who met it.",True),
  C("A delay.","The server went down at 3 pm, ___ meant we lost two hours.",["which","that","what","who"],"which","Whole idea: , which (not what).",True)])
u3=U("compare","Comparisons: -er, most, as...as, the more","B1",
 "Short adjectives add -er / -est; longer ones use more / most. Use as + adjective + as for equality, not as...as for less, and 'the + comparative, the + comparative' to show two things changing together.",
 "ছোট adjective-এ -er/-est, বড়টায় more/most। সমান বোঝাতে as...as। 'যত বেশি... তত বেশি' = the more..., the more...।",
 [("Comparative / superlative","cheap → cheaper → the cheapest · expensive → more expensive → the most expensive"),("Equality","as + adjective + as: as busy as Dhaka · not as fast as"),("Double comparative","The sooner we start, the sooner we finish.")],
 [("Than after comparatives, never 'from'.","comparative-এর পরে than, from নয়।","Chattogram is smaller than Dhaka."),
  ("Never double: more better is wrong.","more + -er একসাথে নয়।","This plan is better."),
  ("Superlative + the + in / of.","সর্বোচ্চ = the + -est।","It's the busiest road in the city."),
  ("Not as...as = less.","কম বোঝাতে not as...as।","The bus is not as fast as the metro."),
  ("The more..., the more...","যত... তত...।","The more you practise, the more confident you become.")],
 ["than","the most","as ... as","the more ... the more","irregular: good, bad, far"],
 [("Dhaka is bigger from Rajshahi.","Dhaka is bigger than Rajshahi.","Than, not from.","থেকে = than।"),
  ("This laptop is more better.","This laptop is better.","Better is already comparative.","more better ভুল।"),
  ("More you work, more you earn.","The more you work, the more you earn.","Both halves need the.","দুই অংশেই the।")],
 [C("Comparing cities.","Living in Dhaka is more expensive ___ living in Rajshahi.",["than","from","to","as"],"than","Comparative + than."),
  C("The traffic.","This is ___ road in the whole city.",["the busiest","the most busy","busiest","the busier"],"the busiest","Short adjective: the -est."),
  T("Transport.","The bus isn't as fast ___ the metro rail.","one word",["as"],"Not as ... as."),
  T("Work advice.","The earlier you start, ___ better the result.","one word",["the"],"The + comparative, the + comparative."),
  F("Pick the correct sentence.",["Her presentation was more better than mine.","Her presentation was better than mine.","Her presentation was more good than mine.","Her presentation was better from mine."],"Her presentation was better than mine.","Good → better; than."),
  B("ঢাকায় যত বেশি থাকি, তত বেশি ভালো লাগে।",["The longer I live in Dhaka, the more I like it.","More I live in Dhaka, more I like it.","The longer I live in Dhaka, more I like it.","Longer I live in Dhaka, the more I like it."],"The longer I live in Dhaka, the more I like it.","Both halves: the + comparative."),
  C("Rafi's two jobs.","His new job is ___ his old one: same salary, same hours.",["as good as","as better as","so good than","good as"],"as good as","Equality: as + adjective + as.",True),
  C("A bad week.","This is the ___ week I've had all year.",["worst","baddest","most bad","worse"],"worst","Bad → worse → worst.",True)])
save("relatives","Relative clauses and comparisons",
 "Join ideas smoothly with who, which, that, whose and where, use commas correctly, and compare people, places and plans like a fluent speaker.",
 "who, which, whose, where দিয়ে বাক্য জোড়া লাগানো, কমার সঠিক ব্যবহার, আর তুলনা করার নিয়ম শিখুন।",[u1,u2,u3],
 [C("Describing a colleague.","I work with someone ___ husband is a pilot.",["whose","who","who's","which"],"whose","Possession: whose."),
  C("A holiday.","Cox's Bazar, ___ has the longest natural sea beach, is always busy.",["which","that","where","who"],"which","Non-defining: commas + which."),
  T("A memory.","That's the café ___ I first met my wife.","relative word",["where","at which"],"Place: where."),
  F("Pick the correct sentence.",["Our manager, that is from Khulna, is very calm.","Our manager, who is from Khulna, is very calm.","Our manager who is from Khulna, is very calm.","Our manager, which is from Khulna, is very calm."],"Our manager, who is from Khulna, is very calm.","Commas + who."),
  B("এটা আমার দেখা সবচেয়ে সুন্দর জায়গা।",["This is the most beautiful place I have ever seen.","This is the beautifulest place I have ever seen.","This is more beautiful place I have ever seen.","This is the most beautiful place which I have ever seen it."],"This is the most beautiful place I have ever seen.","Long adjective: the most."),
  C("Comparing offers.","The second offer is much ___ than the first.",["better","more better","best","more good"],"better","Good → better."),
  T("Prices.","The more you buy, the ___ you pay per unit.","one word",["less"],"The more..., the less..."),
  F("Pick the correct sentence.",["The laptop I bought it is very slow.","The laptop I bought is very slow.","The laptop who I bought is very slow.","The laptop where I bought is very slow."],"The laptop I bought is very slow.","Object relative dropped; no extra 'it'.",True)],
 [("Is it a person?","Use who (or that in a defining clause).","Thing: which / that. Place: where. Possession: whose."),
  ("Is the information extra, about a name or the only one?","Put it between commas and use who / which, never that.","No commas; that is fine and can often be dropped if it is the object.")])
